    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt();
        int x = 0;
        int[] xi = new int[N];
        int[] ri = new int[N];

        for (int i = 0; i < N; i++) {
            xi[i] = scanner.nextInt();
            ri[i] = scanner.nextInt();
        }

        System.out.println(f(xi, ri));
